// 回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	return thresholdFor(loadThresholds(), warehouse)
}

// thresholdFor 返回 thresholds 里该仓库的阈值；没有该仓库就回退默认值。
func thresholdFor(thresholds map[string]int, warehouse string) int {
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取仓库到阈值的映射。任何一个值不是整数字面量，或文件读取、
// 解析失败时，都返回 nil，让调用方整体回退默认值——坏配置不该让服务崩掉，
// 也不该悄悄把某个仓库的阈值变成 0（那会让它永不触发低库存）。
func loadThresholds() map[string]int {
	data, err := os.ReadFile(thresholdsPath)
	if err != nil {
		return nil
	}
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil
	}
	thresholds := make(map[string]int, len(raw))
	for warehouse, value := range raw {
		// 用 *int 接：JSON null 会落成 nil（而不是像直接解到 int 那样不报错地变成 0），
		// 小数、指数、字符串、布尔也会在这里报错。
		var threshold *int
		if err := json.Unmarshal(value, &threshold); err != nil || threshold == nil {
			return nil
		}
		thresholds[warehouse] = *threshold
	}
	return thresholds
